import{escapeHtml,safeUrl,ordered}from './news-utils.mjs';
const box=document.querySelector('#latestNews');try{const r=await fetch('news.json',{cache:'no-store'});if(!r.ok)throw Error();const feed=await r.json();box.innerHTML=`<div class="latest-heading"><strong>材料动态</strong><a href="news.html">查看全部与历史 ↗</a></div>`+ordered(feed.items).slice(0,3).map(x=>`<a class="latest-row" href="${escapeHtml(safeUrl(x.url))}" target="_blank" rel="noopener noreferrer"><time>${escapeHtml(x.published_at)}</time><span>${escapeHtml(x.title)}</span><small>原文 ↗</small></a>`).join('')}catch{box.innerHTML='<a href="news.html">查看材料动态与历史 ↗</a>'}
